            P('Если воздействовать на клавишу управления стеклом водителя в режиме подъема/опускания не более 1,5 секунд, то после прекращения воздействия стекло останавливается. Если время воздействия превышает 1,5 секунды, то после прекращения воздействия стекло продолжает движение в автоматическом режиме до распознавания препятствия, но не более 10 секунд.'),
            P('Автоматический режим движения стекла прекращается при подъеме до упора или до распознавания препятствия, при воздействии на любую клавишу управления стеклоподъемниками на МДВ и при выключении зажигания.'),
            NOTE('Автоматический режим подъема/опускания стекла реализован изначально в заводской поставке МДВ. Возможно отключение режима автоматического управления стеклоподъемником двери водителя при помощи диагностического тестера у дилера LADA.'),
            W('При закрытии окон с электрическими стеклоподъемниками возможно защемление пальцев рук и других частей тела, что может привести к серьезной травме. При пользовании электрическими стеклоподъемниками будьте внимательны, особенно если в автомобиле или рядом с ним находятся дети. Убедитесь, что поднимающееся стекло ничего не защемит. В случае защемления немедленно прекратите подъем стекла и включите его опускание.', 'danger'),
            P('Ответственность за неправильное пользование электрическими стеклоподъемниками несет водитель автомобиля. Он должен разъяснить пассажирам правила пользования и предупредить об опасностях при неправильном пользовании электрическими стеклоподъемниками.'),
            P('Не разрешайте детям пользоваться переключателями электростеклоподъемников. Выходя из автомобиля, обязательно вынимайте ключ из выключателя зажигания, чтобы отключить электростеклоподъемники и избежать случайного травмирования.'),
