            P('Если на заднем сиденье находятся дети, рекомендуем ключом повернуть шлиц защелки 1 (рис. 8) примерно на 45° до упора. Причем в правой двери защелку необходимо поворачивать по часовой стрелке, а в левой — против часовой стрелки. В этом случае, при поднятой кнопке блокировки, дверь открывается только снаружи, а внутренняя рукоятка имеет свободный ход. Для обеспечения возможности открывания дверей изнутри поверните шлиц защелки в обратном направлении.'),
