            P('В систему крепления ISOFIX входят два нижних кронштейна ISOFIX и кронштейн для верхнего страховочного ремня ISOFIX. Нижние кронштейны ISOFIX расположены у основания спинки заднего сиденья. Места их расположения отмечены на спинке круглой пиктограммой. Перед подсоединением фиксаторов детского удерживающего устройства ISOFIX необходимо освободить зону расположения нижних кронштейнов ISOFIX, разместив замки задних ремней безопасности по линии стыка подушки и спинки заднего сиденья.'),
