            P('При выборе детской удерживающей системы ISOFIX необходимо руководствоваться информацией, приведенной в таблице 1а. Детское удерживающее устройство ISOFIX может устанавливаться в Вашем автомобиле только в том случае, если оно соответствует требованиям Европейского стандарта ECE R 44.'),
