            P('При работающем двигателе расход моторного масла — нормальное явление. Величина расхода масла зависит от стиля вождения автомобиля и определяется нагрузкой на двигатель и частотой вращения коленчатого вала. В начальный период эксплуатации расход масла несколько повышен.'),
            P('Поэтому регулярно, особенно перед дальними поездками, следует проверять уровень масла в картере двигателя.'),
            P('Уровень масла проверяется на холодном неработающем двигателе при нахождении автомобиля на горизонтальной поверхности. Уровень должен находиться между метками MIN и MAX указателя уровня масла 1 (рис. 49а) или между верхним и нижним краями рифленой поверхности указателя 1 (рис. 49б) в зависимости от модели двигателя. При необходимости доливка масла производится через горловину, закрываемую пробкой 2.'),
            fig('49а', wide=True),
