            P('После доливки уровень масла следует контролировать не ранее чем через три минуты, чтобы долитая порция масла успела стечь в картер. Для правильного измерения необходимо вставлять указатель 1 уровня масла в его установочное отверстие до упора.'),
            W('Не допускается превышение уровня масла в картере двигателя выше метки MAX указателя 1 уровня масла. В противном случае масло через систему вентиляции картера будет попадать в камеру сгорания и вместе с отработавшими газами выбрасываться в атмосферу, а продукты сгорания масла могут привести к отказу нейтрализатора.', 'warning'),
