            P('После запуска двигателя, перевода селектора в положения R, А или М, перевода ноги с педали тормоза на педаль акселератора и выключения ручного тормоза автомобиль начинает движение. В режиме А переключение передач выполняется полностью автоматически.'),
            P('Водитель может использовать рычаг переключения передач для завершения автоматического режима в любое время и выполнять ручное вмешательство в программе автоматического привода. Если повышение или понижение передачи приведет к завышенным оборотам двигателя, неправомерное переключение передач будет блокировано.'),
            P('Компьютер отображает в комбинации приборов следующую информацию, касающуюся функционирования роботизированной коробки передач:'),
