    if 'Инструкция пользования автоматизированной трансмиссией (АМТ)' in by_title:
        by_title['Инструкция пользования автоматизированной трансмиссией (АМТ)']['blocks'] = [
            P('Трансмиссия АМТ основана на базе пятиступенчатой механической коробки передач 2180. Управление процессами переключения передач осуществляется синхронной работой двух электромеханических актуаторов, которые управляются контроллером трансмиссии TCU. Актуатор переключения установлен вместо штатного тросового механизма переключения.'),
            P('Автомобиль с трансмиссией АМТ не имеет педали сцепления, все процессы оперирования сцеплением автоматизированы и обеспечиваются электрическими сигналами, отрабатываемыми актуатором сцепления.'),
            P('Все режимы трансмиссии индицированы буквенными обозначениями на декоративной крышке селектора и дублируются в цифровом виде на электронном табло комбинации приборов. Индикация режима работы: N, R, A, M. Индикация включенной передачи режима работы: 1, 2, 3, 4, 5. Индикация всех режимов, кроме R, производится одновременно с номером включенной передачи.'),
            P('Педальный узел автомобиля с трансмиссией АМТ управляется исключительно правой ногой.'),
            H('Основные режимы движения'),
            LIST([
                'автоматический режим A — переключение передач полностью автоматическое и выполняется без участия водителя;',
                'мануальный режим M — водитель легким касанием переводит селектор в положения «+» (повышение передач) и «–» (понижение передач).',
            ]),
            P('Запуск двигателя возможен только в нейтральном положении N и при нажатой педали тормоза. При повороте ключа зажигания возможна задержка запуска двигателя 2–3 секунды, связанная с процедурой инициализации системы управления трансмиссией.'),
            P('Движение возможно после перевода селектора в положение A или M при нажатой педали тормоза. При нажатии на педаль акселератора сцепление включается и автомобиль начинает движение. Если педаль акселератора не нажимается, автомобиль не трогается, но может свободно катиться, несмотря на включенный режим движения и включенную передачу. Режима ползучести трансмиссия АМТ не имеет конструктивно.'),
            P('Если после запуска двигателя перевести селектор в положение M, включится первая передача. Далее можно переключать передачи в ручном режиме. Понижение передач при снижении скорости осуществляется автоматически. Режим M позволяет проводить комбинированное торможение рабочим тормозом и двигателем последовательным переключением передач на более низшие.'),
            P('На всех режимах движения ощущаются задержки, обусловленные работой системы синхронизации коробки передач в процессе переключения. Режим A настроен на максимально комфортный стиль вождения, и задержки несколько более длительны, чем на режиме M. Режимы A и M обладают функцией резкого ускорения kick-down.'),
            P('В движении возможно переводить рычаг селектора из положения A в положение M и обратно. Это удобно, например, при затяжных подъемах или при необходимости предварительно перейти на более низкую передачу перед обгоном.'),
            W('Для обеспечения безопасности при управлении автомобилем с прицепом в сложных дорожных условиях (горные, грунтовые и заснеженные дороги либо дороги с поврежденным покрытием) использовать прицеп массой не более 450 кг и рекомендуется перейти на режим M. При движении по дорогам со скользким покрытием в режиме A рекомендуется плавное управление педалью акселератора для исключения пробуксовки колес.', 'warning'),
            P('При переключении рычага из положения A в положение R в движении система заблокирует включение передачи заднего хода. При этом индикатор символа режима R будет мигать. Для исключения поломки трансмиссии система не позволит включить передачу, не соответствующую скорости.'),
            P('В случае необходимости раскачивания автомобиля, например при буксовании, возможно переключение режимов R–A и обратно через N, но без задержки в N и без нажатия педали тормоза при условии, что скорость не превышает 3 км/ч. При скорости выше 3 км/ч переключение с A на R или с R на A возможно только при нажатии на тормоз.'),
            P('Выключать зажигание можно в любом положении селектора. В положении N автомобиль может катиться и его можно буксировать, в других положениях селектора автомобиль остается на выбранном режиме, и сцепление замкнуто. На уклонах необходимо дополнительно обеспечить предупреждение самопроизвольного качения автомобиля ручным тормозом.'),
            P('При въезде на крутые подъемы при малой скорости следует учитывать, что при снижении оборотов двигателя ниже минимальных сцепление выключится автоматически, чтобы избежать остановки двигателя. На уклоне это может привести к скатыванию автомобиля вниз. В таком случае необходимо обеспечивать движение с оборотами двигателя, превышающими минимальные.'),
            P('При разряженной АКБ запуск двигателя от колес буксировкой возможен. Для этого требуется разогнать автомобиль на нейтрали N до скорости выше 7 км/ч, затем переключить селектор в положение A. Контроллер трансмиссии зарегистрирует скорость и активирует функцию запуска с колес.'),
            W('Включение индикатора «шестеренка» в комбинации приборов указывает на неисправность трансмиссии. В этом случае необходима диагностика системы АМТ специализированным диагностическим оборудованием. При перегреве сцепления индикатор работает в мигающем режиме и дополнительно сцепление пульсирует в процессе трогания, чтобы предупредить водителя.', 'warning'),
        ]

    if 'Основы безопасной эксплуатации автомобиля' in by_title:
        by_title['Основы безопасной эксплуатации автомобиля']['blocks'] = [
            P('Ваша безопасность и охрана среды обитания зависят от технической исправности автомобиля и соблюдения правил его эксплуатации. Нижеприведенные рекомендации в значительной степени повысят безопасность на дорогах и позволят сохранить транспортное средство в исправном состоянии.'),
            H('Меры предосторожности при эксплуатации автомобиля'),
            P('Не превышайте нагрузки автомобиля, указанной в руководстве. Перегрузка приводит к повреждению элементов подвески, преждевременному износу шин и потере устойчивости автомобиля.'),
            P('Не допускайте быстрой езды по дорогам с нарушенным покрытием, так как резкие удары могут деформировать детали силового агрегата, кузова и подвески. В случае сильных ударов, например при наезде на бордюр, обратитесь к дилеру LADA для проверки состояния автомобиля.'),
            P('Регулярно проверяйте состояние защитных резиновых чехлов рейки рулевого механизма, шаровых опор, тяги переключения передач, шарниров привода передних колес, а также защитных колпачков шарниров рулевых тяг. Поврежденные чехлы и колпачки немедленно заменяйте, а неправильно установленные или скрученные — поправляйте.'),
            W('Для смазки узлов и агрегатов применяйте материалы, рекомендуемые заводом-изготовителем в приложении 1, либо обратитесь за соответствующей информацией к дилеру LADA. Применение других материалов может привести к преждевременному износу или повреждению узлов и агрегатов.', 'warning'),
            W('Двигатель автомобиля рассчитан на применение бензина с октановым числом не ниже, чем указано в приложении 1. Эксплуатация автомобиля на бензинах с меньшим октановым числом приведет к отказу двигателя.', 'warning'),
            P('Регулярно проверяйте давление воздуха в шинах, так как эксплуатация шин с давлением, отличающимся от рекомендованного, приводит к их преждевременному износу, увеличению расхода топлива и ухудшению устойчивости и управляемости автомобиля.'),
            W('Разница давления на одной оси всего на 0,02–0,03 МПа ухудшает управляемость, а при экстренном торможении может привести к заносу.', 'danger'),
            P('Во избежание пробуксовки сцепления после переключения передачи и включения сцепления снимите ногу с педали. В процессе движения не держите ногу на педали сцепления и не держите руку на рычаге переключения передач.'),
            W('Не держите ногу на педали сцепления и не держите руку на рычаге переключения передач во время движения — это приводит к повреждению и преждевременному износу деталей механизма переключения передач.', 'warning'),
            P('Следите за чистотой клемм и зажимов аккумуляторной батареи и надежностью их соединения. Окисление клемм и ненадежное соединение вызывают искрение в месте контакта и могут привести к отказу электронного оборудования автомобиля.'),
            W('На автомобиле установлена система зажигания высокой энергии. При работающем двигателе касание элементов системы зажигания опасно. Не рекомендуется проверять цепи высокого напряжения «на искру».', 'danger'),
            P('Демонтаж высоковольтных проводов с приборов системы зажигания осуществляйте только за защитный колпачок. Не оставляйте на длительное время ключ в выключателе зажигания при неработающем двигателе.'),
            P('Избегайте резкого открывания дверей в конце их хода. Не оставляйте незакрытыми двери на остановке при сильном ветре, чтобы избежать деформации передних кромок дверей.'),
            P('Зимой, когда слой льда или снега на опускных стеклах затрудняет их передвижение, не применяйте чрезмерных усилий при вращении ручки. Для предотвращения отказа электростеклоподъемников очищайте стекла дверей от льда и снега.'),
            H('Эксплуатация нового автомобиля'),
            P('Во время обкатки нового автомобиля до пробега первых 2000 км:'),
            LIST([
                'после пробега первой тысячи километров проконтролируйте затяжку болтов крепления колес и при необходимости подтяните;',
                'при движении автомобиля не превышайте скорости 110 км/ч и частоты вращения двигателя 3500 мин⁻¹;',
                'своевременно, в соответствии с дорожными условиями, включайте высшие передачи в коробке передач, избегая перегрузки двигателя;',
                'не производите буксировку прицепа или другого автомобиля;',
                'не допускайте резкого трогания с места, разворота с пробуксовкой передних колес и других режимов, ведущих к повышенным нагрузкам на трансмиссию.',
            ]),
            W('Работа новых шин, тормозных колодок и дисков, сцепления оптимизируется только после их обкатки. Поэтому первые 500 км используйте сдержанную манеру движения с умеренными ускорениями. Если указанные компоненты будут заменены, выполните обкатку заново.', 'warning'),
            H('Подготовка автомобиля к движению'),
            W('Перед выездом из гаража или с места стоянки проверьте техническое состояние автомобиля.', 'warning'),
            OL([
                'Проверьте и доведите до нормы давление воздуха в шинах.',
                'Проверьте уровень масла в картере двигателя и при необходимости доведите его до нормы.',
                'Проверьте уровни охлаждающей, тормозной и омывающей жидкостей и при необходимости доведите их до нормы.',
                'Проверьте исправность ламп внешних световых приборов и их чистоту.',
                'Проверьте функционирование системы стеклоочистки.',
                'Проверьте правильность установки зеркал, сидений и ремней безопасности.',
                'Проверьте исправность рабочей тормозной системы и стояночного тормоза.',
            ]),
            P('Наличие следов масел и эксплуатационных жидкостей под автомобилем свидетельствует о негерметичности его узлов и агрегатов. В этом случае необходимо обратиться к дилеру LADA для выявления и устранения причин.'),
            W('Не откладывая, устраняйте обнаруженные неисправности у дилера LADA.', 'warning'),
            H('Посадка водителя за рулем'),
            W('Безопасная техника вождения автомобиля во многом зависит от правильной посадки водителя. Правильная посадка — водитель достаточно плотно опирается на спинку сиденья, ноги при полном ходе педалей вытянуты не полностью, а обе руки, слегка согнутые в локтевых суставах, удерживают верхнюю часть рулевого колеса. Положение тела должно быть устойчивым, но не напряженным.', 'danger'),
            H('Пуск двигателя'),
            P('Перед пуском двигателя вставьте ключ в выключатель зажигания, поставьте автомобиль на ручной тормоз, выжмите до упора педаль сцепления, переведите рычаг переключения передач в нейтральное положение. Затем включите зажигание и сделайте паузу в несколько секунд, чтобы электробензонасос успел поднять давление в топливной рампе до рабочего значения.'),
            W('Во время пуска двигателя не следует нажимать на педаль акселератора. Пуск двигателя оптимизирован до температуры окружающей среды минус 27 °С без участия водителя в управлении дроссельной заслонкой. При полном нажатии на педаль акселератора в режиме пуска подача топлива блокируется для продувки цилиндров.', 'warning'),
            OL([
                'Включите стартер. Нажатую до упора педаль сцепления удерживайте до окончания пуска и выхода двигателя на устойчивый холостой ход. После пуска двигателя отпустите ключ зажигания.',
                'Если в течение 10 секунд работы стартера двигатель не пустился, повторите пуск не ранее чем через 40 секунд.',
                'Если вторая попытка пуска была безуспешной, третью начните не ранее чем через 40 секунд с полностью нажатой педалью акселератора (режим продувки цилиндров). После 6–8 секунд продувки плавно отпустите педаль акселератора.',
            ]),
            NOTE('Запрещается включать стартер более чем на 10 секунд.'),
            W('Несоблюдение рекомендаций по пуску двигателя может привести к перегрузке стартера и выходу его из строя. Не допускается при помощи стартера начинать движение автомобиля.', 'danger'),
            P('Если и третья попытка пуска не удалась, возможны следующие причины: температура окружающей среды ниже минус 27 °С, двигатель неисправен либо имело место отклонение от рекомендаций по пуску. Для решения проблемы необходимо обратиться к дилеру LADA.'),
            W('Выхлопные газы ядовиты. Помещение, в котором производится пуск и прогрев двигателя, должно хорошо вентилироваться.', 'danger'),
            H('Особенности эксплуатации автомобиля с системой впрыска топлива'),
            P('Загорание сигнализатора «Двигатель» при работающем двигателе сигнализирует о наличии неисправности, но не означает, что двигатель должен быть немедленно остановлен — контроллер имеет резервные режимы, позволяющие двигателю работать в условиях, близких к нормальным.'),
            NOTE('Жидкостные выделения из выхлопной трубы относятся к конденсату и являются естественным рабочим процессом, неисправностью не являются.'),
            P('Двигатель с системой впрыска топлива при наличии нейтрализатора и датчика кислорода работает исправно только при использовании неэтилированного бензина. Этилированный бензин в короткий срок приводит к отказу этих элементов, увеличению расхода топлива и ухудшению динамики автомобиля.'),
            W('Нейтрализатор является дорогостоящим узлом и может быть поврежден пропусками воспламенения в цилиндрах двигателя. При появлении пропусков нужно принять срочные меры по их устранению. Автомобили, оснащенные нейтрализаторами, можно заводить буксировкой только при холодном двигателе. Предпочтительнее запускать двигатель с использованием другого аккумулятора или внешнего источника тока 12 В. Нельзя использовать стартер для передвижения автомобиля.', 'danger'),
            W('Категорически запрещается помещать и хранить в моторном отсеке легковоспламеняющиеся материалы и предметы (ветошь, бумагу и т. п.).', 'danger'),
            H('Особенности эксплуатации автомобиля с электромеханическим усилителем рулевого управления'),
            P('На автомобиль устанавливается электромеханический усилитель рулевого управления, благодаря которому управление автомобилем становится легче. Усилитель расположен в рулевой колонке и отслеживает управляющие воздействия на рулевое управление в зависимости от скорости движения автомобиля.'),
            W('Малое усилие на рулевом колесе, обеспечиваемое электроусилителем, позволяет вращать рулевое колесо с большой скоростью. В крайних положениях возможны незначительные удары ограничителя хода рейки о картер, сопровождаемые небольшим стуком. Необходимо контролировать скорость вращения рулевого колеса в крайних положениях и не прикладывать повышенных усилий при упоре рейки в ограничитель.', 'warning'),
            P('Не рекомендуется эксплуатация автомобиля с неисправным электроусилителем, когда загорается контрольный сигнализатор в комбинации приборов. Причина неисправности должна быть как можно быстрее установлена и устранена у дилера LADA.'),
            P('Электроусилитель не работает или может отключаться при неработающем двигателе, при отключенном датчике скорости, при длительной стоянке автомобиля с работающим двигателем при частоте вращения более 1500 мин⁻¹, при снижении напряжения бортовой сети или при низкой частоте холостого хода двигателя. Такие отключения вызваны алгоритмом работы электроусилителя и не являются признаком неисправности.'),
        ]

    if 'Движение автомобиля' in by_title:
        by_title['Движение автомобиля']['blocks'] = [
            P('Движение автомобиля допустимо начинать только после освобождения стекол салона от льда, снега и запотевания до уровня, обеспечивающего безопасность движения.'),
            P('При отрицательной температуре окружающей среды движение рекомендуется начинать не ранее чем через 30 секунд после пуска двигателя. Для частичного прогрева масла в коробке передач желательно, чтобы двигатель некоторое время поработал на минимальной частоте холостого хода при отпущенной педали сцепления. Если такой возможности нет, после длительной стоянки при низкой температуре некоторое время двигайтесь на низших передачах с невысокой частотой вращения двигателя.'),
            W('Во избежание повреждения механизма переключения передач внутри коробки передач из-за застывшего масла не прикладывайте чрезмерных усилий к рычагу переключения передач и не производите ударного включения передач.', 'warning'),
            P('Техника вождения переднеприводного автомобиля специфична и несколько отличается от техники вождения заднеприводного автомобиля, особенно при движении на поворотах. При подъезде к повороту заранее оцените его и, в зависимости от радиуса и состояния дорожного покрытия, уменьшите скорость. Поворот желательно проходить в режиме «натяга», постепенно увеличивая частоту вращения двигателя.'),
            P('По возможности водите автомобиль без резких ускорений и замедлений, так как это приводит к повышенному износу шин и увеличению расхода топлива. Расход топлива также увеличивается при недостаточном давлении воздуха в шинах, изношенных или загрязненных свечах зажигания и использовании моторных масел повышенной вязкости.'),
            W('Резкое трогание с места, в том числе с включенным ручным тормозом, разворот с пробуксовкой передних колес при максимальной частоте вращения двигателя не допускается.', 'danger'),
            P('Во время движения следите за работой различных систем по приборам и сигнализаторам. В нормальных условиях сигнализаторы красного цвета гореть не должны — их включение сигнализирует о необходимости проверки соответствующей системы у дилера LADA.'),
            P('При движении по лужам снижайте скорость во избежание аквапланирования. После преодоления луж, после мойки автомобиля или при длительном движении по мокрой дороге, когда в тормозные механизмы колес попадает вода, произведите при движении несколько плавных торможений, чтобы просушить диски, барабаны и тормозные накладки.'),
            W('Во избежание повреждения двигателя, вызванного попаданием в цилиндры воды через воздухозаборник, не допускается преодолевать скопления воды глубиной более 300 мм. Движение по более глубоким лужам выполняйте с минимально возможной скоростью, чтобы исключить образование волны, способной залить воздухозаборник двигателя.', 'danger'),
            W('Особое внимание проявляйте в первые минуты после начала дождя, так как смоченная пыль на дорожном покрытии образует скользкую пленку, резко снижающую сцепление шин с дорогой. Не проводите в дождливую погоду обгон, если водяное облако из-под колес впереди идущего автомобиля полностью закрывает обзор зоны обгона.', 'warning'),
            P('Чтобы не двигаться в водяном шлейфе от впереди идущих автомобилей, увеличивайте дистанцию и снижайте скорость движения. При движении вдоль тротуаров во время дождя или после него при проезде через лужи снижайте скорость, чтобы брызги из-под колес не попадали на пешеходов.'),
            H('Движение зимой'),
            P('Для создания комфортных условий в салоне автомобиля при температуре окружающей среды ниже нуля прогрейте двигатель. Перед включением стеклоочистителей убедитесь, что щетки не примерзли к стеклу. При вождении в условиях снегопада и образования ледяной корки на стекле используйте функции системы вентиляции и отопления салона.'),
            W('Налипание снега на рычагах стеклоочистителя затрудняет их нормальную работу. Остановитесь с соблюдением правил дорожного движения, выключите стеклоочистители и удалите снег.', 'warning'),
            P('Будьте очень осторожны на мокрых или скользких участках дорог — не допускайте резких торможений и резкого нажатия и отпускания педали акселератора. При возникновении заноса поверните руль в сторону заноса и плавной работой рулем и педалью газа выровняйте автомобиль.'),
            P('В местах пересечения дорог часто возникает наледь за счет пробуксовки колес при трогании с места. Поэтому при приближении к таким местам заранее, на сухом участке, начинайте снижение скорости.'),
            P('После длительной стоянки в передних и задних амортизаторах возможны гидравлические шумы, воспринимаемые как стук подвески. Шумы будут уменьшаться и полностью исчезнут по мере прогрева амортизаторов при движении.'),
            H('Движение в горной местности'),
            W('При движении на подъем своевременно переходите на низшие передачи, не допуская перегрузки двигателя и рывков автомобиля. На длинных спусках используйте торможение двигателем с частичным использованием рабочих тормозов. Не допускайте спуска с выключенным сцеплением и использованием только рабочих тормозов.', 'warning'),
            P('В горной местности держитесь правой стороны дороги. Меньшая ширина дороги и сложный профиль трассы требуют большего внимания и осторожности. При остановке на подъеме или на спуске выверните руль до упора так, чтобы в случае самопроизвольного начала движения автомобиль был прижат колесом к бордюру или склону.'),
            W('Если автомобиль с АКП JATCO застрял в грязи, снегу, на песчаном грунте или другой поверхности дорожного покрытия, на котором происходит буксование колес, убедитесь, что время нажатия на педаль акселератора не превышает 30 секунд, а после каждого нажатия выдержана пауза около 3 минут при минимальной частоте холостого хода двигателя. Длительная пробуксовка колес может привести к перегреву и серьезным поломкам трансмиссии.', 'warning'),
        ]

    if 'Торможение и стоянка' in by_title:
        by_title['Торможение и стоянка']['blocks'] = [
            W('Научитесь тормозить плавно, не допуская блокировки колес. Еще лучше использовать плавное притормаживание рабочими тормозами с одновременным переходом на пониженные передачи в коробке передач.', 'warning'),
            P('Использование для торможения двигателем на скользкой или мокрой дороге слишком низкой для фактической скорости передачи, а также резкое включение сцепления, может вызвать нарушение сцепления колес с дорогой и спровоцировать занос автомобиля.'),
            P('Плавное торможение обеспечивает курсовую устойчивость автомобиля даже на скользких участках дороги и, кроме того, способствует экономии топлива, увеличивает ресурс шин и тормозных накладок.'),
            P('Если при исправных подвесках, правильных углах установки передних колес и нормальном давлении воздуха в шинах при торможении автомобиль уводит в сторону и Вам приходится доворачивать руль, чтобы сохранить направление движения, необходимо обратиться к дилеру LADA.'),
            P('Садясь впервые за руль автомобиля, проверьте работу тормозов при умеренных скоростях движения для приобретения первого навыка торможения.'),
            W('Во избежание прилипания тормозных колодок к барабанам не ставьте автомобиль на длительную стоянку с включенным стояночным тормозом.', 'warning'),
            W('В случае отказа одного из контуров тормозной системы торможение обеспечивает второй контур. При этом ход педали тормоза увеличивается и снижается эффективность торможения, что в первый момент может быть оценено Вами как полный отказ тормозов. В данном случае не отпускайте педаль и не производите многократных нажатий — это только увеличит тормозной путь. Необходимо нажимать на педаль до получения максимально возможного эффекта торможения.', 'danger'),
            P('При остановке или стоянке на подъеме или спуске включите стояночный тормоз и, соответственно, первую или заднюю передачу в коробке передач.'),
            P('Чтобы тормозные колодки не примерзли к барабанам после движения по мокрым дорогам при низких температурах, не оставляйте автомобиль на открытой площадке с включенным стояночным тормозом, не просушив тормоза плавными торможениями при движении к месту стоянки.'),
            P('При парковке автомобиля во время снегопада рекомендуется отжать от стекла рычаги стеклоочистителей во избежание примерзания щеток.'),
            W('Не выключайте зажигание при движении автомобиля. С остановкой двигателя резко возрастает усилие, которое необходимо приложить к педали тормоза для торможения автомобиля.', 'danger'),
            H('Антиблокировочная система тормозов (АБС)'),
            P('Автомобили оснащаются антиблокировочной системой тормозов, которая предотвращает блокировку колес при торможении, обеспечивая сохранение заданной траектории движения, возможность корректировки траектории поворотом рулевого колеса и минимальный тормозной путь в условиях хорошего сцепления с дорогой.'),
            P('АБС выполняет также дополнительную функцию электронного распределения тормозных сил, которая обеспечивает оптимальное соотношение тормозных сил передних и задних колес автомобиля.'),
            W('Во избежание ограничения работоспособности АБС не устанавливайте на автомобиль шины разной размерности.', 'warning'),
            P('При экстренном торможении максимально быстро и с максимальным усилием нажимайте на тормозную педаль и удерживайте ее, не отпуская до конца торможения. При изменении направления движения во время торможения также не отпускайте тормозную педаль.'),
            W('Прерывистое торможение на автомобилях с АБС увеличивает тормозной путь. Срабатывание АБС сопровождается незначительной пульсацией тормозной педали и характерным шумом исполнительных механизмов. АБС прекращает работать при снижении скорости автомобиля до 3 км/ч.', 'warning'),
            H('Система электронного контроля устойчивости'),
            P('В вариантном исполнении автомобили оснащаются системой электронного контроля устойчивости, которая в любых дорожных условиях при отклонении автомобиля от заданной водителем траектории движения автоматически притормаживает одно или несколько колес и, при необходимости, уменьшает крутящий момент двигателя, компенсируя отклонение и сохраняя устойчивость и управляемость автомобиля.'),
            P('Система ЭКУ выполняет также функции АБС, электронного распределения тормозных сил и противобуксовочную функцию, которая оптимизирует проскальзывание колес при трогании и разгоне.'),
            W('Срабатывание системы ЭКУ, сопровождаемое миганием сигнализатора системы ЭКУ, свидетельствует о достижении предела сцепления шин с дорожным покрытием. Во избежание потери управления автомобилем необходимо приспособить стиль вождения к действительным дорожным условиям.', 'warning'),
            H('Функция HHC'),
            P('В вариантном исполнении система ЭКУ снабжена функцией предотвращения скатывания автомобиля при трогании передним или задним ходом на подъеме (HHC — Hill Hold Control). При остановке на подъеме с уклоном более 4 % удерживайте нажатой педаль тормоза с усилием, достаточным для обеспечения неподвижности автомобиля. При последующем отпускании педали тормоза и нажатии педали акселератора функция HHC сохраняет давление в гидравлическом приводе тормозов до момента трогания, но в течение не более 2 секунд.'),
            P('Срабатывание HHC сопровождается характерным шумом исполнительных механизмов. HHC не работает при использовании стояночного тормоза или неисправности ESC.'),
            H('Система вспомогательного торможения'),
            P('Автомобили с АБС или системой ЭКУ оснащаются вакуумным усилителем тормоза с системой вспомогательного торможения, которая по высокой скорости нажатия на педаль тормоза распознает необходимость экстренного торможения и автоматически обеспечивает максимальную эффективность торможения в течение всего времени, пока нажата педаль тормоза.'),
        ]

