            fig('48', wide=True),
            P('Препятствие сзади автомобиля система обнаруживает при помощи ультразвуковых датчиков, работающих по принципу эхолокации. Предупреждение водителя и информирование о расстоянии до препятствия осуществляется акустическим сигнализатором.'),
            P('При включенном зажигании и включенной задней передаче система включается автоматически, при этом раздается короткий звуковой сигнал высокого тона. Если препятствие находится в зоне обнаружения, система информирует водителя прерывистым или непрерывным звуковым сигналом в зависимости от расстояния до препятствия. Начиная с расстояния около 100 см частота сигналов растет, а при расстоянии между бампером и препятствием около 40 см сигнал становится непрерывным.'),
            W('Система парковки является вспомогательной системой, которая помогает водителю оценить расстояние до обнаруженного препятствия. Даже при ее работе водитель обязан максимально снизить скорость движения и остановить автомобиль при появлении непрерывного звукового сигнала.', 'warning'),
            P('Движение задним ходом считается маневром повышенной опасности. Водитель обязан убедиться в безопасности маневра перед его началом и во время движения, контролируя обстановку сзади автомобиля при помощи боковых зеркал и зеркала заднего вида.'),
            P('Система парковки включает блок управления с функцией диагностики, установленный в багажном отделении, три ультразвуковых датчика в заднем бампере и звуковой сигнализатор, установленный на одном кронштейне с блоком управления.'),
            H('Особенности работы и эксплуатации системы парковки'),
            OL([
                'После включения системы раздается короткий звуковой сигнал высокого тона, далее блок управления проводит комплексную проверку с целью обнаружения дефектных датчиков или других неисправностей системы.',
                'Если обнаружен дефектный датчик или другая неисправность, после сигнала включения раздается непрерывный звуковой сигнал низкого тона в течение 3 секунд. Затем система укажет неисправный датчик: один короткий сигнал — левый датчик, два — центральный, три — правый. Если неисправен блок управления, раздается сигнал низкого тона длительностью около 2 секунд. После сигнализации о наличии неисправности система отключается.',
                'Из-за особенностей распространения ультразвуковых волн система может не определять низкие, тонкие, заостренные предметы, пуховую одежду, мягкий снег и т. п. При приближении к препятствиям типа «пандус» необходимо использовать и другие способы контроля за обстановкой сзади автомобиля.',
                'При эксплуатации автомобиля с прицепом для отключения системы парковки необходимо соединить между собой колодки двух проводов: черно-голубого и черного, выводы которых находятся около заднего левого фонаря.',
                'Для предотвращения неправильной работы датчики должны поддерживаться чистыми от снега, льда и грязи. При очистке датчиков нельзя пользоваться твердыми или острыми предметами. Датчики нужно беречь от ударов. Замена неисправных компонентов системы производится у дилера LADA.',
            ]),
