def assign_figures_to_sections(section_search_texts, figures):
    assigned = {idx: [] for idx in range(len(TOC))}
    for figure in sorted(figures, key=lambda item: (item['page'], item['index'])):
        candidates = section_candidate_indices(figure['page'])
        fid = figure['figure_id']
        ref_scores = []
        for idx in candidates:
            text = section_search_texts[idx]
            count = len(re.findall(rf'рис\.?\s*{re.escape(fid)}\b', text, re.I))
            if count:
                start_gap = abs(TOC[idx]['page'] - figure['page'])
                ref_scores.append((-count, start_gap, -idx, idx))
        if ref_scores:
            ref_scores.sort()
            chosen = ref_scores[0][3]
        else:
            chosen = candidates[-1] if candidates else len(TOC) - 1
        assigned[chosen].append(figure)
    return assigned


def paragraphs_to_blocks(paragraphs, assigned_figures):
    assigned_figures = list(assigned_figures)
    by_id = defaultdict(list)
    for figure in assigned_figures:
        by_id[figure['figure_id']].append(figure)

    used_keys = set()
    blocks = []

    def append_figures(ids):
        for fid in ids:
            for figure in by_id.get(fid, []):
                if figure['key'] not in used_keys:
                    blocks.append(make_figure_block(figure))
                    used_keys.add(figure['key'])
                    break

    i = 0
    while i < len(paragraphs):
        p = paragraphs[i].strip()
        if not p:
            i += 1
            continue
        if is_caption_paragraph(p):
            caption_ids = [extract_figure_id(part) for part in split_caption_paragraph(p)]
            append_figures([fid for fid in caption_ids if fid])
            i += 1
            continue

        upper = p.upper() == p and re.search(r'[А-ЯЁ]', p)
        if upper and len(p) <= 120 and not p.startswith(('ВНИМАНИЕ', 'ПРЕДУПРЕЖДЕНИЕ')):
            blocks.append({'t': 'h', 'v': p.title()})
            append_figures(figure_ref_ids_in_text(p))
            i += 1
            continue

        if p.startswith('ВНИМАНИЕ!') or p == 'ВНИМАНИЕ':
            v = p[len('ВНИМАНИЕ!'):].strip() if p.startswith('ВНИМАНИЕ!') else ''
            refs_text = p
            if not v and i + 1 < len(paragraphs) and not is_caption_paragraph(paragraphs[i + 1].strip()):
                v = paragraphs[i + 1].strip()
                refs_text += ' ' + v
                i += 1
            blocks.append({'t': 'warning', 'v': v or p, 'icon': '⚠️', 'level': 'warning'})
            append_figures(figure_ref_ids_in_text(refs_text))
            i += 1
            continue

        if p.startswith('ПРЕДУПРЕЖДЕНИЕ!') or p.startswith('ПРЕДУПРЕЖДЕНИЕ') or p.startswith('Предупреждение') or p.startswith('ПРЕДОСТЕРЕЖЕНИЕ!') or p.startswith('ПРЕДОСТЕРЕЖЕНИЕ'):
            v = re.sub(r'^(ПРЕДУПРЕЖДЕНИЕ|Предупреждение|ПРЕДОСТЕРЕЖЕНИЕ)!?\s*', '', p).strip()
            refs_text = p
            if not v and i + 1 < len(paragraphs) and not is_caption_paragraph(paragraphs[i + 1].strip()):
                v = paragraphs[i + 1].strip()
                refs_text += ' ' + v
                i += 1
            blocks.append({'t': 'warning', 'v': v or p, 'icon': '⚠️', 'level': 'danger'})
            append_figures(figure_ref_ids_in_text(refs_text))
            i += 1
            continue

        if p.startswith('*'):
            blocks.append({'t': 'note', 'v': p.lstrip('* ').strip()})
            append_figures(figure_ref_ids_in_text(p))
            i += 1
            continue

        if re.match(r'^[–•-]', p):
            items = []
            combined = []
            while i < len(paragraphs) and re.match(r'^[–•-]', paragraphs[i].strip()):
                item = re.sub(r'^[–•-]\s*', '', paragraphs[i].strip())
                if item:
                    items.append(item)
                    combined.append(item)
                i += 1
            if items:
                blocks.append({'t': 'list', 'items': items})
                append_figures(figure_ref_ids_in_text(' '.join(combined)))
            continue

        if re.match(r'^\d+[\.)]\s+', p):
            items = []
            combined = []
            while i < len(paragraphs) and re.match(r'^\d+[\.)]\s+', paragraphs[i].strip()):
                item = re.sub(r'^\d+[\.)]\s+', '', paragraphs[i].strip())
                if item:
                    items.append(item)
                    combined.append(item)
                i += 1
            if items:
                blocks.append({'t': 'ol', 'items': items})
                append_figures(figure_ref_ids_in_text(' '.join(combined)))
            continue

        if len(p) <= 90 and not re.search(r'[.!?…:;]$', p) and not re.match(r'^(\d|[IVX]+\b)', p):
            blocks.append({'t': 'h', 'v': p})
            append_figures(figure_ref_ids_in_text(p))
            i += 1
            continue

        blocks.append({'t': 'p', 'v': p})
        append_figures(figure_ref_ids_in_text(p))
        i += 1

    for figure in assigned_figures:
        if figure['key'] not in used_keys:
            blocks.append(make_figure_block(figure))
            used_keys.add(figure['key'])

    return blocks


def main():
    if not PDF_PATH.exists():
        raise SystemExit(f'PDF not found: {PDF_PATH}')

    doc = fitz.open(PDF_PATH)
    pages = [extract_page_text(page) for page in doc]
    TEXT_PATH.write_text('\n\n'.join(pages), encoding='utf-8')

    page_offsets = []
    cursor = 0
    for text in pages:
        page_offsets.append(cursor)
        cursor += len(text) + 2
    full_text = '\n\n'.join(pages)

    found_positions = []
    search_cursor = 0
    for entry in TOC:
        search_text = entry.get('search', entry['title'])
        start_at = max(page_offsets[entry['page'] - 1], search_cursor)
        match = make_pattern(search_text).search(full_text, start_at)
        if not match:
            raise SystemExit(f'Heading not found: {entry["title"]} (search: {search_text})')
        found_positions.append((match.start(), match.end()))
        search_cursor = match.end()

    blueprints = []
    section_search_texts = []
    for idx, entry in enumerate(TOC):
        start, end_heading = found_positions[idx]
        next_start = found_positions[idx + 1][0] if idx + 1 < len(found_positions) else len(full_text)
        snippet = full_text[end_heading:next_start].strip()
        raw_paragraphs = [p.strip() for p in re.split(r'\n{2,}', snippet) if p.strip()]
        paragraphs = preprocess_paragraphs(raw_paragraphs)
        search_text = ' '.join(p for p in paragraphs if not is_caption_paragraph(p))
        blueprints.append({'entry': entry, 'paragraphs': paragraphs})
        section_search_texts.append(search_text)

    figures = load_figures()
    assigned_figures = assign_figures_to_sections(section_search_texts, figures)

    sections = []
    structure = []
    for idx, blueprint in enumerate(blueprints):
        entry = blueprint['entry']
        paragraphs = blueprint['paragraphs']
        assigned_items = assigned_figures.get(idx, [])
        blocks = paragraphs_to_blocks(paragraphs, assigned_items)
        if not blocks:
            blocks = [{'t': 'note', 'v': 'Раздел требует ручной вычитки после автоматического извлечения из PDF.'}]

        category_slug = CATEGORY_SLUGS[entry['category']]
        file_slug = slugify(entry['title']) + '.html'
        path = f'{category_slug}/{file_slug}'
        tags = [entry['title'], 'LADA Kalina', entry['category'].title()]
        sections.append({
            'category': entry['category'],
            'title': entry['title'],
            'path': path,
            'tags': tags,
            'blocks': blocks,
        })
        structure.append({
            'category': entry['category'],
            'title': entry['title'],
            'search': entry.get('search', entry['title']),
            'page': entry['page'],
            'path': path,
            'blocks_count': len(blocks),
            'figures_count': sum(1 for block in blocks if block.get('t') == 'figure'),
            'figure_ids': [item['figure_id'] for item in assigned_items],
            'figure_keys': [item['key'] for item in assigned_items],
        })

    apply_manual_section_fixes(sections, figures)

    for section in sections:
        section['blocks'] = [block for block in section['blocks'] if not is_noise_block(block)]

    by_path = {section['path']: section for section in sections}
    for item in structure:
        section = by_path[item['path']]
        item['blocks_count'] = len(section['blocks'])
        item['figures_count'] = sum(1 for block in section['blocks'] if block.get('t') == 'figure')

    DATA_PATH.write_text(
        '// Данные раздела LADA Kalina (сгенерировано build_data.py)\nconst SECTIONS =' +
        json.dumps(sections, ensure_ascii=False, separators=(',', ':')) + ';\n',
        encoding='utf-8'
    )
    STRUCTURE_PATH.write_text(json.dumps(structure, ensure_ascii=False, indent=2), encoding='utf-8')
    total_figures = sum(1 for section in sections for block in section['blocks'] if block.get('t') == 'figure')
    print(f'OK: sections={len(sections)} figures_embedded={total_figures} data={DATA_PATH} text={TEXT_PATH}')


if __name__ == '__main__':
    main()
